const nonProfTeachers = `-- name: NonProfTeachers :many
select id, fullname, shortname from teacher
where semester_id = $1 and id > 0 and not is_prof and is_active
order by fullname
`

type NonProfTeachersRow struct {
	ID        int
	Fullname  string
	Shortname string
}

// The persons a FK07 prof may report a demand for: everybody without the prof flag.
func (q *Queries) NonProfTeachers(ctx context.Context, semesterID string) ([]NonProfTeachersRow, error) {
	rows, err := q.db.Query(ctx, nonProfTeachers, semesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []NonProfTeachersRow{}
	for rows.Next() {
		var i NonProfTeachersRow
		if err := rows.Scan(&i.ID, &i.Fullname, &i.Shortname); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const openInquiry = `-- name: OpenInquiry :one
update inquiry
set state = 'OPEN', opened_at = now(), opened_by = $1::text, closed_at = null, closed_by = null,
    updated_at = now()
where semester_id = $2 and kind = $3
returning semester_id, kind, state, deadline, intro, opened_at, opened_by, closed_at, closed_by, updated_at
`

type OpenInquiryParams struct {
	Actor      string
	SemesterID string
	Kind       string
}

func (q *Queries) OpenInquiry(ctx context.Context, arg OpenInquiryParams) (Inquiry, error) {
	row := q.db.QueryRow(ctx, openInquiry, arg.Actor, arg.SemesterID, arg.Kind)
	var i Inquiry
	err := row.Scan(
		&i.SemesterID,
		&i.Kind,
		&i.State,
		&i.Deadline,
		&i.Intro,
		&i.OpenedAt,
		&i.OpenedBy,
		&i.ClosedAt,
		&i.ClosedBy,
		&i.UpdatedAt,
	)
	return i, err
}

const preplanReporters = `-- name: PreplanReporters :many
select distinct t.id from teacher t
where t.semester_id = $1::text and t.id = any($2::int[])
  and t.is_prof and t.fk = 'FK07'
union
select distinct e.main_examer_id from exam e
where e.semester_id = $3::text and e.source = 'zpa'
  and e.main_examer_id = any($2::int[])
`

type PreplanReportersParams struct {
	TeacherSemester string
	Ids             []int
	ExamSemester    string
}

// Of the given ZPA persons, the ones who may report a PREPLAN demand: a prof of FK07 in
// the newest teacher mirror, or a main examiner in the newest semester with ZPA exams.
func (q *Queries) PreplanReporters(ctx context.Context, arg PreplanReportersParams) ([]int, error) {
	rows, err := q.db.Query(ctx, preplanReporters, arg.TeacherSemester, arg.Ids, arg.ExamSemester)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int{}
	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reviewSubmission = `-- name: ReviewSubmission :execrows
update inquiry_submission
set review_state = $1, reviewed_revision = revision, reviewed_by = $2::text,
    reviewed_at = now(), review_note = $3
where semester_id = $4 and id = $5 and revision = $6
`

type ReviewSubmissionParams struct {
	ReviewState string
	Actor       string
	Note        string
	SemesterID  string
	ID          int64
	Revision    int
}

func (q *Queries) ReviewSubmission(ctx context.Context, arg ReviewSubmissionParams) (int64, error) {
	result, err := q.db.Exec(ctx, reviewSubmission,
		arg.ReviewState,
		arg.Actor,
		arg.Note,
		arg.SemesterID,
		arg.ID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

