const updatePreplanExamFromPortal = `-- name: UpdatePreplanExamFromPortal :execrows
update preplan_exam
set exam_kind         = case when $1::bool then $2::text else exam_kind end,
    module            = case when $3::bool then $4::text else module end,
    programs          = case when $5::bool then $6::text[] else programs end,
    expected_students = case when $7::bool then $8::int else expected_students end,
    duration_min      = case when $9::bool then $10::int else duration_min end,
    examer_id         = case when $11::bool then $12::int else examer_id end,
    examer_name       = case when $11::bool then $13::text else examer_name end
where semester_id = $14 and id = $15
`

type UpdatePreplanExamFromPortalParams struct {
	SetKind          bool
	ExamKind         string
	SetModule        bool
	Module           string
	SetPrograms      bool
	Programs         []string
	SetStudents      bool
	ExpectedStudents int
	SetDuration      bool
	DurationMin      *int
	SetExamer        bool
	ExamerID         int
	ExamerName       string
	SemesterID       string
	ID               int
}

// Pre-exam writes on behalf of the portal, semester-explicit. Only the columns the
// examiner states; a planner's correction of another column survives.
func (q *Queries) UpdatePreplanExamFromPortal(ctx context.Context, arg UpdatePreplanExamFromPortalParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePreplanExamFromPortal,
		arg.SetKind,
		arg.ExamKind,
		arg.SetModule,
		arg.Module,
		arg.SetPrograms,
		arg.Programs,
		arg.SetStudents,
		arg.ExpectedStudents,
		arg.SetDuration,
		arg.DurationMin,
		arg.SetExamer,
		arg.ExamerID,
		arg.ExamerName,
		arg.SemesterID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

