const upsertInquiry = `-- name: UpsertInquiry :one
insert into inquiry (semester_id, kind, deadline, intro)
values ($1, $2, $3, $4)
on conflict (semester_id, kind) do update
    set deadline = excluded.deadline, intro = excluded.intro, updated_at = now()
returning semester_id, kind, state, deadline, intro, opened_at, opened_by, closed_at, closed_by, updated_at
`

type UpsertInquiryParams struct {
	SemesterID string
	Kind       string
	Deadline   *time.Time
	Intro      string
}

func (q *Queries) UpsertInquiry(ctx context.Context, arg UpsertInquiryParams) (Inquiry, error) {
	row := q.db.QueryRow(ctx, upsertInquiry,
		arg.SemesterID,
		arg.Kind,
		arg.Deadline,
		arg.Intro,
	)
	var i Inquiry
	err := row.Scan(
		&i.SemesterID,
		&i.Kind,
		&i.State,
		&i.Deadline,
		&i.Intro,
		&i.OpenedAt,
		&i.OpenedBy,
		&i.ClosedAt,
		&i.ClosedBy,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertNotificationMode = `-- name: UpsertNotificationMode :one
insert into notification_setting (email, mode, mailed_up_to, seen_up_to)
values ($1, $2, $3::bigint, $3::bigint)
on conflict (email) do update
    set mode = excluded.mode,
        mailed_up_to = case when notification_setting.mode = 'OFF' and excluded.mode <> 'OFF'
                            then excluded.mailed_up_to else notification_setting.mailed_up_to end,
        updated_at = now()
returning email, mode, mailed_up_to, seen_up_to, updated_at
`

type UpsertNotificationModeParams struct {
	Email   string
	Mode    string
	StartAt int64
}

// First enabling starts at the current state: no backlog.
func (q *Queries) UpsertNotificationMode(ctx context.Context, arg UpsertNotificationModeParams) (NotificationSetting, error) {
	row := q.db.QueryRow(ctx, upsertNotificationMode, arg.Email, arg.Mode, arg.StartAt)
	var i NotificationSetting
	err := row.Scan(
		&i.Email,
		&i.Mode,
		&i.MailedUpTo,
		&i.SeenUpTo,
		&i.UpdatedAt,
	)
	return i, err
}
